from vigenere import get_blocks, sub, BLOCKLENGTH,SHIFT

CTXT = ""


def uncbc(ctxt):
    blocks = get_blocks(ctxt)
    ptxt = "" 
    for i in range(1,len(blocks)):
        ptxt = ptxt + sub(blocks[i],blocks[i-1])
    return(ptxt)

print(uncbc(CTXT))

